import memfs from 'memfs'
import type { FileSystem } from '@servicenow/sdk-build-core'
import { typeCheckProject } from '../../src/util/ui-build'
import { createProject } from '../test-utils'

describe('typeCheckProject', () => {
    test('should pass type checking when clientDir has valid TypeScript files', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `const greeting: string = 'Hello, world!';\nconsole.log(greeting);`,
            '/project/client/utils.ts': `export function add(a: number, b: number): number { return a + b; }`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should fail type checking when clientDir has TypeScript errors', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `const greeting: string = 123;\nconsole.log(greeting);`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).toThrow('Type check failed!')
    })

    test('should handle TSX files correctly', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/component.tsx': `
export const Component = () => <div>Hello</div>;
`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should not throw when clientDir does not exist', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should not throw when clientDir is not configured', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: undefined,
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should use tsconfig.json when it exists in clientDir', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/tsconfig.json': JSON.stringify({
                compilerOptions: {
                    strict: true,
                    target: 'ES2020',
                    module: 'ES2020',
                },
            }),
            '/project/client/index.ts': `const greeting: string = 'Hello';\nconsole.log(greeting);`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const mockLogger = {
            debug: jest.fn(),
            info: jest.fn(),
            warn: jest.fn(),
            error: jest.fn(),
        }

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            logger: mockLogger as any,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
        expect(mockLogger.debug).toHaveBeenCalledWith(
            expect.stringContaining('Using client tsconfig.json for type checking')
        )
    })

    test('should warn when tsconfig.json does not exist and use default options', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `const greeting: string = 'Hello';\nconsole.log(greeting);`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const mockLogger = {
            debug: jest.fn(),
            info: jest.fn(),
            warn: jest.fn(),
            error: jest.fn(),
        }

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            logger: mockLogger as any,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
        expect(mockLogger.warn).toHaveBeenCalledWith(
            'No client tsconfig.json found, using default compiler options for type checking'
        )
    })

    test('should log success message when type checking passes', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `const greeting: string = 'Hello';\nconsole.log(greeting);`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const mockLogger = {
            debug: jest.fn(),
            info: jest.fn(),
            warn: jest.fn(),
            error: jest.fn(),
        }

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            logger: mockLogger as any,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        typeCheckProject(project)
        expect(mockLogger.info).toHaveBeenCalledWith('Type check completed successfully')
    })

    test('should check multiple TypeScript files in subdirectories', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `import { add } from './utils/math';\nconsole.log(add(1, 2));`,
            '/project/client/utils/math.ts': `export function add(a: number, b: number): number { return a + b; }`,
            '/project/client/components/button.tsx': `export const Button = () => <button>Click</button>;`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should include .d.ts declaration files in type checking', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `import { MyType } from './types';\nconst x: MyType = { value: 42 };`,
            '/project/client/types.d.ts': `export interface MyType { value: number; }`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should fail with descriptive error for type mismatches', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `
function greet(name: string): string {
    return 'Hello, ' + name;
}
greet(123);
`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).toThrow('Type check failed!')
    })

    test('should exclude node_modules from type checking', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/index.ts': `const greeting: string = 'Hello';\nconsole.log(greeting);`,
            '/project/client/node_modules/some-lib/index.ts': `const invalid: string = 123;`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should handle empty clientDir', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
        })
        vol.mkdirSync('/project/client', { recursive: true })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        expect(() => typeCheckProject(project)).not.toThrow()
    })

    test('should log the files being type checked', () => {
        const vol = memfs.Volume.fromJSON({
            '/project/package.json': JSON.stringify({ name: 'x_test', version: '1.0.0' }),
            '/project/client/file1.ts': `const a: string = 'test';`,
            '/project/client/file2.ts': `const b: number = 42;`,
            '/project/client/file3.tsx': `const c = <div>Test</div>;`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const mockLogger = {
            debug: jest.fn(),
            info: jest.fn(),
            warn: jest.fn(),
            error: jest.fn(),
        }

        const project = createProject({
            rootDir: '/project',
            fileSystem: fs,
            logger: mockLogger as any,
            config: {
                scope: 'x_test',
                scopeId: Array(32).fill('1').join(''),
                clientDir: 'client',
            },
        })

        typeCheckProject(project)

        expect(mockLogger.debug).toHaveBeenCalledWith(expect.stringContaining('Type checking 3 client source files'))
        expect(mockLogger.debug).toHaveBeenCalledWith(expect.stringContaining('/project/client/file1.ts'))
        expect(mockLogger.debug).toHaveBeenCalledWith(expect.stringContaining('/project/client/file2.ts'))
        expect(mockLogger.debug).toHaveBeenCalledWith(expect.stringContaining('/project/client/file3.tsx'))
    })
})
